contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint256 cBalBefore = address(c).balance;
        uint256 myBalBefore = address(this).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        require(address(c).balance == cBalBefore + amount);
        require(address(this).balance == myBalBefore - amount);

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        uint256 cBalAfter = address(c).balance;
        uint256 myBalAfter = address(this).balance;

        assert(cBalAfter == cBalBefore && myBalAfter == myBalBefore);
    }

    receive() external payable {}
}

